package com.project7.localmanager;
import java.io.*;import java.util.*;
final class MultiWishResolver {
 static final class Decision {final HistoryCatalog.Leaf leaf;final HistoryCatalog.Edge outer;final int wishRow,randomId;Decision(HistoryCatalog.Leaf l,HistoryCatalog.Edge o,int row,int rr){leaf=l;outer=o;wishRow=row;randomId=rr;}}
 static List<Map<?,?>>remaining(MultiWishSpec spec,MultiWishState state,int gid)throws Exception{List<Map<?,?>>r=new ArrayList<>();for(Map<?,?>row:spec.groups.get(gid))if(!state.groups.get(gid).finished.contains(DynamicCatalog.num(row.get("id"))))r.add(row);return r;}
 static Map<Integer,WishProbability.Fraction>probabilities(MultiWishSpec spec,MultiWishState state)throws Exception{Map<Integer,List<Map<?,?>>>active=new TreeMap<>();WishProbability.Fraction totalFixed=WishProbability.ZERO;int nonfixed=0;for(int gid:spec.groups.keySet()){List<Map<?,?>>rows=remaining(spec,state,gid);if(rows.isEmpty())continue;active.put(gid,rows);WishProbability.Fraction fixed=WishProbability.ZERO;for(Map<?,?>row:rows)if(row.containsKey("fix_rate"))fixed=fixed.add(WishProbability.Fraction.decimal(row.get("fix_rate")));totalFixed=totalFixed.add(fixed);if(fixed.compare(WishProbability.ZERO)==0)nonfixed++;}WishCatalog.need(totalFixed.compare(WishProbability.ONE)<=0,"fixed mass");WishProbability.Fraction left=WishProbability.ONE.add(new WishProbability.Fraction(totalFixed.n.negate(),totalFixed.d));Map<Integer,WishProbability.Fraction>result=new TreeMap<>();for(Map.Entry<Integer,List<Map<?,?>>>e:active.entrySet()){List<Map<?,?>>rows=e.getValue();WishProbability.Fraction mass=WishProbability.ZERO;int total=0;for(Map<?,?>row:rows){if(row.containsKey("fix_rate"))mass=mass.add(WishProbability.Fraction.decimal(row.get("fix_rate")));total=Math.addExact(total,DynamicCatalog.num(row.get("wish_weight")));}if(mass.compare(WishProbability.ZERO)==0){Map<?,?>r=rows.get(0);mass=WishProbability.wish(r.get("begin_rate"),r.get("step_rate"),DynamicCatalog.num(r.get("times")),state.groups.get(e.getKey()).count);WishProbability.Fraction cap=left.divide(new WishProbability.Fraction(nonfixed,1));if(mass.compare(cap)>0)mass=cap;}for(Map<?,?>row:rows){int weight=DynamicCatalog.num(row.get("wish_weight"));WishCatalog.need(weight>=0,"wish row weight");result.put(DynamicCatalog.num(row.get("id")),mass.multiply(total==0?new WishProbability.Fraction(1,rows.size()):new WishProbability.Fraction(weight,total)));}}return result;}
 static Decision resolve(MultiWishSpec spec,MultiWishState state,byte[]profile,int ordinal,Random random)throws Exception{List<Map<?,?>>forced=new ArrayList<>();for(int gid:spec.groups.keySet())for(Map<?,?>row:remaining(spec,state,gid))if(row.containsKey("fix_rate")&&row.containsKey("safe_times")&&((long)state.groups.get(gid).count+1)>=DynamicCatalog.num(row.get("safe_times")))forced.add(row);WishCatalog.need(forced.size()<=1,"multiple safety gates");if(!forced.isEmpty()){Map<?,?>r=forced.get(0);return new Decision(WishSource.pick(r,"reward",random),null,DynamicCatalog.num(r.get("id")),0);}
  Map<Integer,WishProbability.Fraction>prob=probabilities(spec,state);List<Integer>ids=new ArrayList<>(prob.keySet());List<WishProbability.Fraction>mass=new ArrayList<>(prob.values());WishProbability.Fraction total=WishProbability.ZERO;for(WishProbability.Fraction p:mass)total=total.add(p);mass.add(WishProbability.ONE.add(new WishProbability.Fraction(total.n.negate(),total.d)));int picked=WishProbability.pick(random,mass);if(picked<ids.size()){int id=ids.get(picked);return new Decision(WishSource.pick(WishCatalog.row(WishCatalog.ready().wish,id),"reward",random),null,id,0);}
  HistoryCatalog graph=HistoryDrawPolicy.dynamicCatalog();HistoryCatalog.Spec source=graph.specs.get(spec.pool);HistoryCatalog.Edge outer=source.defaults.get(ordinal);if(outer==null)outer=source.base.pick(random);Map<?,?>normal=WishCatalog.ready().normals.containsKey(outer.source)?WishCatalog.row(WishCatalog.ready().normals,outer.source):null;int rr=outer.target;
  if(normal!=null&&normal.containsKey("replace_reward")){int best=-1;List<?>chosen=null;for(Object o:DynamicCatalog.list(normal.get("replace_reward"))){List<?>pair=DynamicCatalog.list(o),conditions=DynamicCatalog.list(pair.get(0));boolean match=true;for(Object hero:conditions)match&=LocalResourceEngine.ownsHero(profile,DynamicCatalog.num(hero));if(!match)continue;List<?>refs=DynamicCatalog.list(pair.get(1));if(conditions.size()>best){best=conditions.size();chosen=refs;}else if(conditions.size()==best)WishCatalog.need(chosen.equals(refs),"ambiguous normal replacement");}if(chosen!=null){WishCatalog.need(chosen.size()==1,"replacement RR shape");rr=DynamicCatalog.num(chosen.get(0));Map<?,?>replacement=WishCatalog.row(WishCatalog.ready().replacement,rr);List<?>edges=DynamicCatalog.list(replacement.get("weights"));int sum=0;for(Object e:edges){int w=DynamicCatalog.num(DynamicCatalog.list(e).get(1));WishCatalog.need(w>=0,"replacement negative");sum=Math.addExact(sum,w);}int point=random.nextInt(sum);for(Object e:edges){List<?>pair=DynamicCatalog.list(e);point-=DynamicCatalog.num(pair.get(1));if(point<0)return new Decision(WishSource.leaf(DynamicCatalog.num(pair.get(0))),outer,0,rr);}throw new AssertionError();}}
  return new Decision(graph.leaves.get(graph.random.get(rr).pick(random).target),outer,0,rr);
 }
}
